() => {
  // Find the cards container
  const cards = document.querySelectorAll('[class*="card"], [class*="Card"]');
  const cardInfo = [];
  cards.forEach(c => {
    cardInfo.push({
      tag: c.tagName,
      className: c.className,
      parentClassName: c.parentElement?.className,
      grandparentClassName: c.parentElement?.parentElement?.className,
    });
  });
  return cardInfo.slice(0, 3);
}

() => {
  // Get the first h2 heading "Dashboard" and then its sibling container
  const h1 = document.querySelector('h1');
  const container = h1?.nextElementSibling;
  if (!container) return 'no container found';

  const style = window.getComputedStyle(container);
  return {
    tag: container.tagName,
    className: container.className,
    id: container.id,
    display: style.display,
    flexWrap: style.flexWrap,
    overflow: style.overflow,
    overflowX: style.overflowX,
    width: style.width,
    maxWidth: style.maxWidth,
    gap: style.gap,
    childCount: container.children.length,
    scrollWidth: container.scrollWidth,
    clientWidth: container.clientWidth,
    innerHTML: container.outerHTML.substring(0, 300)
  };
}

() => {
  const h1 = document.querySelector('h1');
  const container = h1?.nextElementSibling;
  const children = Array.from(container.children);
  return children.map((c, i) => {
    const style = window.getComputedStyle(c);
    return {
      index: i,
      tag: c.tagName,
      display: style.display,
      flex: style.flex,
      flexShrink: style.flexShrink,
      minWidth: style.minWidth,
      width: style.width,
      maxWidth: style.maxWidth,
      overflow: style.overflow,
      childCount: c.children.length,
      textContent: c.textContent?.substring(0, 50)
    };
  });
}

() => {
  const h1 = document.querySelector('h1');
  const container = h1?.nextElementSibling;
  // Check the third card (index 2) - the wide one
  const wideCard = container.children[2];
  const titleEl = wideCard.children[0]; // first child should be the title
  const titleStyle = window.getComputedStyle(titleEl);

  return {
    titleText: titleEl.textContent,
    whiteSpace: titleStyle.whiteSpace,
    overflow: titleStyle.overflow,
    textOverflow: titleStyle.textOverflow,
    wordBreak: titleStyle.wordBreak,
    overflowWrap: titleStyle.overflowWrap,
    titleWidth: titleEl.getBoundingClientRect().width,
    cardWidth: wideCard.getBoundingClientRect().width,
    titleInlineStyle: titleEl.getAttribute('style'),
    cardInlineStyle: wideCard.getAttribute('style'),
  };
}

() => {
  const h1 = document.querySelector('h1');
  const container = h1?.nextElementSibling;
  return {
    containerInlineStyle: container.getAttribute('style'),
    containerComputedDisplay: getComputedStyle(container).display,
    containerComputedFlexWrap: getComputedStyle(container).flexWrap,
    containerComputedOverflow: getComputedStyle(container).overflow,
  };
}

() => {
  const h1 = document.querySelector('h1');
  const container = h1?.nextElementSibling;
  const children = Array.from(container.children);
  const totalCardWidth = children.reduce((sum, c) => sum + c.getBoundingClientRect().width, 0);
  const gaps = (children.length - 1) * 16; // gap: 1rem = 16px
  return {
    containerWidth: container.clientWidth,
    containerScrollWidth: container.scrollWidth,
    totalCardWidth,
    totalWithGaps: totalCardWidth + gaps,
    overflow: container.scrollWidth - container.clientWidth,
    cardWidths: children.map((c, i) => ({
      i,
      w: Math.round(c.getBoundingClientRect().width),
      title: c.children[0]?.textContent?.substring(0, 40)
    }))
  };
}
